// gww-c1 — generated by tools/generate.py from DNA 'gww' (seed 11, energy 0.75)
// 123 BPM · Bm (10A) · 184 bars ≈ 5.98 min · kit: own
// novelty vs source loops (0 = copy, 1 = nothing in common): bass bar 0.75 / 2-bar 0.857 · stab bar 0.75
// DJ structure: intro & outro = drums only (mixable), phrases of 8 bars, constant tempo.
setcpm(123/4)

// ---- live controls (sliders on strudel.cc, plain values elsewhere)
const LIVE = typeof sliderWithID !== 'undefined'
const ENERGY = LIVE ? slider(1.1, 0, 1.5) : 1.1   // hats / perc / shaker level
const STAB = LIVE ? slider(1, 0, 1.5) : 1   // stab level
const BASS_ENV = LIVE ? slider(3, 0, 6) : 3   // bass filter envelope depth
const CUT = 755   // bass cutoff (Hz) in the grooves

// ---- arrangement: [section, bars]. Edit freely, every lane follows.
const SECTIONS = [['intro', 8], ['intro2', 8], ['intro3', 16], ['build', 16], ['groove', 32], ['break', 16], ['rise', 8], ['drop', 24], ['groove2', 24], ['outro', 16], ['outro2', 8], ['outro3', 8]]
const bars = (f) => '<' + SECTIONS.flatMap(([n, l]) => Array.from({length: l}, (_, i) => f(n, i, l))).join(' ') + '>'
const on = (...ns) => bars((n) => ns.includes(n) ? 1 : 0)       // 1 bar = 1 cycle
const seq = (f) => mini(bars(f))
const r2 = (x) => Math.round(x * 100) / 100
const third = (t, n, i, l) => t[n] ? t[n][Math.min(2, Math.floor(3 * i / l))] : 1
const FILL_BEFORE = ['build', 'groove', 'drop', 'groove2']    // last bar = fill
const fillBar = (n, i, l) => i == l - 1 && FILL_BEFORE.includes(n)
// levels per section (3 values = thirds of the section), from the DNA level curves
const LVL_DRUMS = {intro: [0.79, 0.84, 0.89], intro2: [0.89, 0.89, 0.89], intro3: [0.89, 0.89, 0.89], build: [0.89, 0.89, 0.89], groove: [0.98, 0.95, 0.78], break: [0.71, 0.71, 0.71], rise: [0.71, 0.71, 0.71], drop: [0.98, 0.95, 0.78], groove2: [0.98, 0.95, 0.78], outro: [0.98, 0.95, 0.78], outro2: [0.99, 0.99, 0.71], outro3: [0.99, 0.99, 0.71]}
const LVL_BASS = {intro: [0.5, 0.5, 0.5], intro2: [0.5, 0.5, 0.5], intro3: [0.5, 0.5, 0.5], build: [0.5, 0.5, 0.71], groove: [0.87, 0.94, 0.5], break: [0.5, 0.5, 0.5], rise: [0.5, 0.5, 0.71], drop: [0.87, 0.94, 0.5], groove2: [0.87, 0.94, 0.5], outro: [0.87, 0.94, 0.5], outro2: [0.5, 0.5, 0.5], outro3: [0.5, 0.5, 0.5]}
const LVL_STAB = {intro: [0.35, 0.35, 0.35], intro2: [0.35, 0.35, 0.35], intro3: [0.35, 0.35, 0.35], build: [0.35, 0.35, 0.35], groove: [0.64, 0.6, 0.55], break: [1.0, 1.0, 0.99], rise: [1.0, 1.0, 0.99], drop: [0.64, 0.6, 0.55], groove2: [0.64, 0.6, 0.55], outro: [0.64, 0.6, 0.55], outro2: [0.35, 0.35, 0.35], outro3: [0.35, 0.35, 0.35]}

// ---- drums (bar variants: [main, phrase-end variation, (section-end fill)])
const KICK_POS = [1, 0, 1, 1, 0, 1, 1, 1]   // phrase positions (bar % 8) using the variation
const KICK = [
  "bd ~ ~ ~ bd ~ ~ ~ bd ~ ~ ~ bd ~ ~ ~",
  "bd ~ ~ ~ bd ~ ~ ~ bd ~ bd ~ bd ~ ~ ~",
  "bd ~ ~ ~ bd ~ ~ ~ bd ~ ~ ~ ~ ~ bd ~"
]
$: s(seq((n, i, l) => fillBar(n, i, l) ? 2 : KICK_POS[i % 8]).pick(KICK)).bank('RolandTR909').lpf(9000)
  .gain(seq((n, i, l) => r2(1.05 * third(LVL_DRUMS, n, i, l))))
  .mask(on('intro', 'intro2', 'intro3', 'build', 'groove', 'drop', 'groove2', 'outro', 'outro2', 'outro3'))

const CLAP_POS = [0, 0, 0, 0, 0, 0, 0, 1]
const CLAP = [
  "~ ~ ~ ~ cp ~ ~ ~ ~ ~ ~ ~ cp ~ ~ ~",
  "~ ~ ~ ~ cp ~ ~ ~ ~ ~ ~ ~ cp ~ ~ cp"
]
$: s(seq((n, i) => CLAP_POS[i % 8]).pick(CLAP)).bank('RolandTR909').hpf(250)
  .gain(seq((n, i, l) => r2(0.62 * third(LVL_DRUMS, n, i, l))))
  .mask(on('intro3', 'build', 'groove', 'rise', 'drop', 'groove2', 'outro', 'outro2'))

const HAT = [
  "hh ~ hh ~ hh hh hh ~ hh ~ hh ~ hh ~ hh ~",
  "hh ~ hh ~ hh hh hh hh hh ~ hh ~ hh ~ hh hh"
]
$: s(seq((n, i) => i % 8 == 7 ? 1 : 0).pick(HAT)).bank('RolandTR909').hpf(7000)
  .gain("0.307 0.176 0.416 0.189 0.29 0.21 0.407 0.231 0.286 0.176 0.412 0.189 0.286 0.176 0.42 0.189")   // accents x level
  .velocity(ENERGY).postgain(seq((n) => n == 'break' ? .55 : n == 'rise' ? .8 : 1))

// open hats on the off-beats, louder after the break (DNA: the reference's hats open up)
$: s("~ ~ oh ~ ~ ~ oh ~ ~ ~ oh ~ ~ ~ oh ~").bank('RolandTR909').hpf(6000).cut(1)
  .velocity(ENERGY).gain(seq((n, i, l) => r2(0.26 * (n == 'groove' ? .35 + .4 * i / l : 1))))
  .mask(on('groove', 'drop', 'groove2', 'outro'))

$: s("<[~ ~ ~ ~ ~ ~ ~ rim ~ ~ ~ ~ ~ ~ ~ rim] [~ ~ ~ ~ ~ ~ ~ rim ~ ~ ~ ~ ~ rim ~ ~]>").bank('RolandTR909').hpf(400)
  .gain(0.42).velocity(ENERGY).delay(.22).delaytime(0.3659).delayfeedback(.3)
  .mask(on('intro2', 'intro3', 'build', 'groove', 'drop', 'groove2', 'outro'))

$: s("sh sh sh sh sh sh sh sh sh sh sh sh sh sh sh sh").bank('RolandTR808').hpf(5000)
  .gain("[0.11 0.055 0.22 0.066]*4").velocity(ENERGY)
  .mask(on('drop', 'groove2'))

// fills: clap roll on the last bar of a section, rolling build-up in the 'rise'
const FILL = [
  "~",
  "~ ~ ~ ~ ~ ~ ~ ~ cp cp cp cp cp cp cp cp",
  "cp ~ cp ~ cp ~ cp ~ cp ~ cp ~ cp ~ cp ~",
  "cp cp cp cp cp cp cp cp cp cp cp cp cp cp cp cp"
]
$: s(seq((n, i, l) => n == 'rise' ? (i < l / 2 ? 2 : 3) : fillBar(n, i, l) ? 1 : 0).pick(FILL)).bank('RolandTR909')
  .gain(seq((n, i, l) => r2(0.55 * (n == 'rise' ? .3 + .7 * i / l : .8))))
  .hpf(seq((n, i, l) => n == 'rise' ? Math.round(300 + 2500 * i / l) : 300))

// ---- bass: 2-bar loop, root b1, intervals from the DNA vocabulary (generated, not copied)
const BASS = "<[b1 c2@2 ~@13] [b1 c2@3 ~@7 b1 ~@4]>"
$: note(BASS).s('sawtooth').ftype('ladder')
  .lpf(seq((n, i, l) => n == 'build' ? Math.round(180 + (CUT - 180) * i / l) : n == 'rise' ? Math.round(150 + (CUT - 150) * i / l) : CUT)).lpenv(BASS_ENV).lpa(.002).lpd(.14).lps(.15).lpq(9)
  .attack(.004).decay(.2).sustain(.55).release(.04).distort(.25)
  .gain(seq((n, i, l) => r2(.42 * third(LVL_BASS, n, i, l)))).mask(on('build', 'groove', 'rise', 'drop', 'groove2'))
$: note(BASS).s('sine').attack(.004).decay(.3).sustain(.8).release(.04)   // sub layer
  .gain(seq((n, i, l) => r2(.55 * third(LVL_BASS, n, i, l)))).mask(on('build', 'groove', 'drop', 'groove2'))

// ---- stab: short chord motif (rhythm from the DNA 'other' onsets)
const STABS = "<[~@11 [b3,d4,f#4,a4]@2 [b3,d4,f#4,a4] ~@2] [~ [d4,f4,a4,c5] ~@11 [d4,f4,a4,c5] [d4,f4,a4,c5] ~]>"
$: note(STABS).s('supersaw').attack(.002).decay(seq((n) => n == 'break' ? .35 : .13)).sustain(0).release(.08)
  .lpf(seq((n, i, l) => n == 'break' ? Math.round(900 + 2500 * i / l) : 2600)).lpenv(2).lpd(.1).lpq(4).hpf(220)
  .delay(.3).delaytime(0.3659).delayfeedback(seq((n) => n == 'break' ? .55 : .35))
  .gain(seq((n, i, l) => r2(.3 * third(LVL_STAB, n, i, l)))).postgain(STAB).mask(on('groove', 'break', 'rise', 'drop', 'groove2'))

// ---- pad (break): progression Bm C C C, roots by Markov over the DNA bass moves
const PAD = "<[b3,d4,f#4] [c4,e4,g4] [c4,e4,g4] [c4,e4,g4]>"
$: note(PAD).s('supersaw').attack(.6).decay(.5).sustain(.8).release(1.5).hpf(180).lpq(2)
  .lpf(seq((n, i, l) => n == 'break' ? Math.round(500 + 2500 * i / l) : 3000))
  .gain(seq((n, i, l) => n == 'break' ? .34 : r2(.34 * (1 - i / l)))).mask(on('break', 'rise'))
$: s('white').attack(.01).decay(.3).sustain(.7).release(.1)   // noise riser
  .hpf(seq((n, i, l) => Math.round(400 + 8000 * i / l))).gain(seq((n, i, l) => r2(.02 + .1 * i / l))).mask(on('rise'))
